      "proposed_laureates": [
        "Heino Falcke",
        "James M. Moran",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Horizon-scale black-hole images turned strong-field gravity into a directly observable subject and captured the public imagination.",
        "attribution": "Falcke, Moran, and Doeleman each have substantial roles in the scientific and technical path to very-long-baseline imaging, though the result was a large collaboration achievement.",
        "maturity": "The M87 image and later Galactic-center imaging provide compelling, independently analyzed evidence, with continued observations refining the picture.",
        "uncertainties": [
          "The division of credit across the global Event Horizon Telescope collaboration is difficult to compress into a few names."
        ]
      }
    },
    {
      "rank": 5,
